sql-set.sql:

INSERT INTO "McaPolicy" (
    "PolicyNumber", "PolicyName", "LineOfBusinessCode", "PolicyType",
    "StatusCode", "TransactionType", "QuoteId", "RenewalStatus",
    "InsuredId", "InsuredName", "InsuredAddress",
    "EffectiveDate", "ExpirationDate", "OriginalEffectiveDate",
    "AccountingDate", "CancellationDate", "CancelReasonDescription",
    "TotalPremium", "SumInsured", "Deductible", "Currency",
    "ProducerCode", "ProducerName", "UnderwriterId", "UnderwriterName", "AgentCode",
    "VesselName", "VesselType", "CargoType", "RouteFrom", "RouteTo",
    "AircraftRegistration", "FlightNumber", "RiskDescription", "SurveyorName", "Remarks",
    "CreatedBy", "CreatedDateTime", "UpdatedDateTime",
    "IsActive", "IsDeleted", "CustomFields"
)
VALUES (
    @PolicyNumber, @PolicyName, @LineOfBusinessCode, @PolicyType,
    @StatusCode, @TransactionType, @QuoteId, @RenewalStatus,
    @InsuredId, @InsuredName, @InsuredAddress,
    @EffectiveDate, @ExpirationDate, @OriginalEffectiveDate,
    @AccountingDate, @CancellationDate, @CancelReasonDescription,
    @TotalPremium, @SumInsured, @Deductible, @Currency,
    @ProducerCode, @ProducerName, @UnderwriterId, @UnderwriterName, @AgentCode,
    @VesselName, @VesselType, @CargoType, @RouteFrom, @RouteTo,
    @AircraftRegistration, @FlightNumber, @RiskDescription, @SurveyorName, @Remarks,
    @CreatedBy, @CreatedDateTime, @UpdatedDateTime,
    true, false, @CustomFields
)
RETURNING "Id";
